### Description

This Terraform configuration sets up a blue/green deployment with AWS Elastic Beanstalk environments associated with an RDS database. It includes the following components:

1. **AWS Provider Configuration**: Configures the AWS provider with a specific region.
2. **IAM Role and Instance Profile**: Creates an IAM role and an instance profile for EC2 instances in Elastic Beanstalk.
3. **RDS Database Instance**: Sets up an RDS database instance named "my_db".
4. **Database Snapshot**: Takes a snapshot of the RDS database before deployment.
5. **Elastic Beanstalk Application**: Creates an Elastic Beanstalk application named "my_app".
6. **Elastic Beanstalk Environments**: Sets up two environments, "my_app_blue" and "my_app_green", for blue/green deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role and Instance Profile
resource "aws_iam_role" "ec2_eb_role" {
  name = "ec2_eb_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "ec2_eb_role_policy" {
  name = "ec2_eb_role_policy"
  role = aws_iam_role.ec2_eb_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*",
          "cloudwatch:*",
          "ec2:*",
          "elasticbeanstalk:*",
          "autoscaling:*",
          "s3:*",
          "sns:*",
          "rds:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_eb_profile1" {
  name = "ec2_eb_profile1"
  roles = [aws_iam_role.ec2_eb_role.name]
}

# RDS Database Instance
resource "aws_db_instance" "my_db" {
  instance_class = "db.t2.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "8.0"
  username = "admin"
  password = "password"
  db_name = "my_database"
  skip_final_snapshot = false
}

# Database Snapshot
resource "aws_db_snapshot" "my_db_snapshot" {
  db_instance_identifier = aws_db_instance.my_db.id
  db_snapshot_identifier = "my_db_snapshot"
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_app" {
  name = "my_app"
}

# Elastic Beanstalk Environments
resource "aws_elastic_beanstalk_environment" "my_app_blue" {
  application = aws_elastic_beanstalk_application.my_app.name
  name = "my_app_blue"
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  instance_profile = aws_iam_instance_profile.ec2_eb_profile1.name
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name = "EnvironmentType"
    value = "LoadBalanced"
  }
}

resource "aws_elastic_beanstalk_environment" "my_app_green" {
  application = aws_elastic_beanstalk_application.my_app.name
  name = "my_app_green"
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  instance_profile = aws_iam_instance_profile.ec2_eb_profile1.name
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name = "EnvironmentType"
    value = "LoadBalanced"
  }
}
```

