### Description
This Terraform program sets up a multi-region application deployment using AWS services. It includes the following components:

1. **Route 53 Zone**: Manages a domain named `example.com`.
2. **Route 53 Records**: Directs traffic to Elastic Beanstalk environments in `us-east-1` and `eu-west-1`.
3. **Elastic Beanstalk Environments**: Deploys applications in the specified regions.
4. **RDS Instances**: Provides databases for the Elastic Beanstalk environments.
5. **IAM Instance Profile**: Manages the instance profile for the Elastic Beanstalk environments.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Route 53 Zone
resource "aws_route53_zone" "mydomain" {
  name = "example.com"
}

# Route 53 Record for us-east-1
resource "aws_route53_record" "us_east_1" {
  name    = "us-east-1.example.com"
  type    = "A"
  zone_id = aws_route53_zone.mydomain.zone_id
  ttl     = 300

  alias {
    name                   = aws_elastic_beanstalk_environment.myenv_us_east.cname
    zone_id                = aws_elastic_beanstalk_environment.myenv_us_east.arn
    evaluate_target_health = true
  }
}

# Route 53 Record for eu-west-1
resource "aws_route53_record" "eu_west_1" {
  name    = "eu-west-1.example.com"
  type    = "A"
  zone_id = aws_route53_zone.mydomain.zone_id
  ttl     = 300

  alias {
    name                   = aws_elastic_beanstalk_environment.myenv_eu_west.cname
    zone_id                = aws_elastic_beanstalk_environment.myenv_eu_west.arn
    evaluate_target_health = true
  }
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "eb_role" {
  name = "eb_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
