  name = "my_application"
}

# Create an Elastic Beanstalk environment
resource "aws_elastic_beanstalk_environment" "webserver_environment" {
  name                = "webserver_environment"
  application         = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.9"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.micro"
  }

