This Terraform program creates an AWS CodeBuild project with an example IAM role, environment variables, secondary sources, and secondary artifacts. The program includes the necessary resources and configurations to meet the specified requirements.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "example_codebuild_role" {
  name = "example_codebuild_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# S3 Bucket for Secondary Source
resource "aws_s3_bucket" "example_secondary_source_bucket" {
  bucket = "example-secondary-source-bucket"
}

# S3 Bucket for Secondary Artifacts
resource "aws_s3_bucket" "example_secondary_artifact_bucket" {
  bucket = "example-secondary-artifact-bucket"
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example_codebuild_project"
  service_role = aws_iam_role.example_codebuild_role.arn

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type         = "LINUX_CONTAINER"
    certificate  = aws_s3_bucket.example_secondary_source_bucket.arn
  }

  source {
    type     = "S3"
    location = "example-secondary-source-bucket/buildspec.yml"
  }

  secondary_sources {
    source_identifier = "secondary-source"
    type              = "S3"
    location          = "example-secondary-source-bucket/secondary-buildspec.yml"
  }

  secondary_artifacts {
    artifact_identifier = "secondary-artifact"
    type              = "S3"
    location          = "example-secondary-artifact-bucket/artifacts"
  }

  artifacts {
    type = "S3"
    location = "example-secondary-artifact-bucket/main-artifacts"
  }

  environment_variables {
    name  = "EXAMPLE_VAR"
    value = "example_value"
    type  = "PLAINTEXT"
  }
}
```

