}

resource "aws_iam_role" "kinesisanalyticsv2_app_role" {
  name = "kinesisanalyticsv2_app_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_kinesisanalyticsv2_application" "kinesisanalyticsv2_app" {
  name                = "kinesisanalyticsv2_app"
  runtime_environment = "FLINK-1_19"
