### Description
This Terraform program creates a Kinesis Firehose Delivery Stream configured with an extended S3 Destination, including dynamic partitioning. The program also sets up an S3 bucket where the data will be delivered. The necessary IAM roles are created to allow the Firehose service to write to the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "my_s3_bucket" {
  bucket = "my-kinesis-firehose-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_policy" {
  name = "firehose-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.my_s3_bucket.arn,
          "${aws_s3_bucket.my_s3_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "my_kinesis_firehose_delivery_stream" {
  name        = "my-kinesis-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn = aws_iam_role.firehose_role.arn
    bucket_arn = aws_s3_bucket.my_s3_bucket.arn
    buffering_interval = 300
    buffering_size = 5
    compression_format = "UNCOMPRESSED"
    dynamic_partitioning_configuration {
      enabled = true
    }
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **S3 Bucket**: An S3 bucket named `my-kinesis-firehose-bucket-${random_string.suffix.result}` is created. The `${random_string.suffix.result}` ensures a unique bucket name.
3. **IAM Role**: An IAM role named `firehose-delivery-role` is created with a trust policy allowing Firehose to assume the role.
4. **IAM Role Policy**: An IAM policy is attached to the role, granting permissions to perform necessary S3 operations.
5. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose Delivery Stream named `my-kinesis-firehose-stream` is created with an extended S3 destination. Dynamic partitioning is enabled.
6. **Random String**: A random string resource is used to append a suffix to the S3 bucket name to ensure uniqueness.

