  name = "firehose_to_redshift_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_to_redshift_policy" {
  name        = "firehose_to_redshift_policy"
  description = "Policy allowing Firehose to write to Redshift"

