        Action = [
          "redshift:LoadIntoRedshiftFromS3",
          "redshift:DescribeClusters",
          "redshift:GetClusterCredentials",
          "s3:ListBucket",
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_redshift_cluster.redshift_cluster.arn}",
          "arn:aws:s3:::my-bucket",
