### Description

This Terraform program creates a Kinesis Firehose Delivery Stream with a Splunk destination. The program includes the necessary resources and configurations to set up the delivery stream and ensure it can send data to Splunk using the HTTP Event Collector (HEC). The program also sets up a Kinesis Data Stream as the source for the Firehose Delivery Stream.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kinesis_stream" "main" {
  name        = "main"
  shard_count = 1
}

resource "aws_kinesis_firehose_delivery_stream" "my_kinesis_firehose_delivery_stream" {
  name                = "my_kinesis_firehose_delivery_stream"
  destination         = "http_endpoint"

  http_endpoint_configuration {
    url                  = "https://hec.splunk.com/services/collector"
    name                 = "splunk_http_endpoint"
    buffering_interval   = 300
    buffering_size       = 5
    retry_duration       = 300
    s3_backup_mode       = "Failed"
    role_arn             = aws_iam_role.firehose_to_splunk.arn
  }

  kinesis_source_configuration {
    kinesis_stream_arn = aws_kinesis_stream.main.arn
    role_arn           = aws_iam_role.firehose_to_kinesis.arn
  }
}

resource "aws_iam_role" "firehose_to_splunk" {
  name = "firehose_to_splunk"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_to_splunk_policy" {
  name = "firehose_to_splunk_policy"
  role = aws_iam_role.firehose_to_splunk.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "firehose_to_kinesis" {
  name = "firehose_to_kinesis"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_to_kinesis_policy" {
  name = "firehose_to_kinesis_policy"
  role = aws_iam_role.firehose_to_kinesis.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:DescribeStream",
          "kinesis:GetShardIterator",
          "kinesis:GetRecords",
          "kinesis:ListShards"
        ]
        Effect = "Allow"
        Resource = aws_kinesis_stream.main.arn
      }
    ]
  })
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Kinesis Data Stream**: A Kinesis Data Stream named `main` is created with a single shard.
3. **Kinesis Firehose Delivery Stream**: A Firehose Delivery Stream named `my_kinesis_firehose_delivery_stream` is created with an HTTP endpoint destination configured for Splunk.
4. **IAM Roles and Policies**:
   - `firehose_to_splunk`: An IAM role that allows Firehose to send logs to Splunk.
   - `firehose_to_kinesis`: An IAM role that allows Firehose to read from the Kinesis Data Stream.
   - Corresponding policies are attached to these roles to grant the necessary permissions.

This setup ensures that data from the Kinesis Data Stream is delivered to Splunk via the HTTP Event Collector.

