### Description
This Terraform program creates a Kinesis Firehose Delivery Stream configured to deliver data to an OpenSearch destination within a VPC. The program includes the necessary resources for both the Kinesis Firehose Delivery Stream and the OpenSearch Domain, ensuring secure communication between them.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "index_name" {
  description = "The index name for the OpenSearch destination"
  default     = "my-index"
}

variable "role_arn" {
  description = "The IAM role ARN for the OpenSearch destination"
  default     = "arn:aws:iam::123456789012:role/my-opensearch-role"
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name        = "kinesis_stream"
  shard_count = 1
}

resource "aws_opensearch_domain" "opensearch_domain" {
  domain_name = "opensearch_domain"

  ebs_options {
    ebs_enabled = true
    volume_size = 20
  }

  cluster_config {
    instance_type = "t3.medium.search"
  }

  node_to_node_encryption {
    enabled = true
  }

  encrypt_at_rest {
    enabled = true
  }

  vpc_options {
    security_group_ids = ["sg-0123456789abcdef0"]
    subnet_ids         = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]
  }
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name = "firehose_delivery_stream"

  opensearch_configuration {
    domain_arn       = aws_opensearch_domain.opensearch_domain.arn
    index_name       = var.index_name
    role_arn         = var.role_arn
    buffering_interval = 300
    buffering_size   = 5
    s3_backup_mode   = "Failed"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Two variables are defined with default values:
  - `index_name`: The name of the OpenSearch index.
  - `role_arn`: The IAM role ARN required for the OpenSearch destination.
- **Kinesis Stream**: A Kinesis stream named `kinesis_stream` is created with a single shard.
- **OpenSearch Domain**: An OpenSearch domain named `opensearch_domain` is created with EBS options, cluster configuration, node-to-node encryption, encryption at rest, and VPC options.
- **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream named `firehose_delivery_stream` is created with an OpenSearch destination configuration, referencing the OpenSearch domain's ARN, index name, and IAM role ARN. Buffering intervals and sizes are set, and S3 backup mode is configured for failed deliveries.

