### Description

This Terraform program sets up a basic Amazon Kinesis Data Analytics V2 application configured to process data using SQL. The program includes:

1. **IAM Role**: An IAM role named `kinesis_analytics_role` that allows the Kinesis Data Analytics application to execute.
2. **Input Kinesis Stream**: A Kinesis stream named `input_stream` where the application will read data from.
3. **Output Kinesis Stream**: A Kinesis stream named `output_stream` where the application will write processed data to.
4. **Kinesis Data Analytics Application**: A Kinesis Data Analytics V2 application named `basic_sql_app` that uses the SQL runtime environment and processes data from the input stream, writing results to the output stream.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis_analytics_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_kinesis_stream" "input_stream" {
  name = "input_stream"
  shard_count = 1
}

resource "aws_kinesis_stream" "output_stream" {
  name = "output_stream"
  shard_count = 1
}

resource "aws_kinesisanalyticsv2_application" "basic_sql_app" {
  name                  = "basic_sql_app"
  runtime_environment   = "SQL-1_0"
  service_execution_role = aws_iam_role.kinesis_analytics_role.arn

  application_configuration {
    sql_application_configuration {
      input {
        name_prefix = "input_stream"
        kinesis_streams_input {
          resource_arn = aws_kinesis_stream.input_stream.arn
        }
      }

      output {
        name = "output_stream"
        kinesis_streams_output {
          resource_arn = aws_kinesis_stream.output_stream.arn
        }
      }
    }
  }
}
```

