}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "test_eks_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"

  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_subnet" "test_eks_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"

  availability_zone = data.aws_availability_zones.available.names[1]
}

resource "aws_iam_role" "example" {
  name = "${var.cluster_name}-eks"

  assume_role_policy = jsonencode({
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
    Version = "2012-10-17"
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.example.name
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
  role       = aws_iam_role.example.name
}

resource "aws_eks_cluster" "example" {
  name     = var.cluster_name
  role_arn = aws_iam_role.example.arn

  vpc_config {
    subnet_ids = [ aws_subnet.test_eks_1.id, aws_subnet.test_eks_2.id ]
  }

  # Ensure that IAM Role permissions are created before and deleted after EKS Cluster handling.
  # Otherwise, EKS will not be able to properly delete EKS managed EC2 infrastructure such as Security Groups.
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_service_policy,
  ]

  # Manage kubectl configuration
  provisioner "local-exec" {
    command = "aws eks --region ${data.aws_region.current.name} update-kubeconfig --name ${self.name}"
  }

  provisioner "local-exec" {
    when    = destroy
    command = "kubectl config unset users.${self.arn}"
  }
  provisioner "local-exec" {
    when    = destroy
    command = "kubectl config unset clusters.${self.arn}"
  }
  provisioner "local-exec" {
    when    = destroy
    command = "kubectl config unset contexts.${self.arn}"
  }
}

LLM Output #0:
### Description
This Terraform program defines an AWS EKS cluster named based on a provided `cluster_name` variable. It creates an IAM role with necessary permissions and associates it with the EKS cluster. The EKS cluster is configured with VPC subnet IDs for networking. Local-exec provisioners are used to manage kubectl configuration during cluster creation and destruction.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  type        = string
  description = "The name of the EKS cluster"
  default     = "my-eks-cluster"
}

variable "vpc_id" {
  type        = string
  description = "The VPC ID where the EKS cluster will be deployed"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  type        = list(string)
  description = "The subnet IDs for the EKS cluster"
  default     = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_iam_role" "eks_role" {
  name               = "${var.cluster_name}-eks-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_role.name
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_role.arn

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  lifecycle {
    ignore_changes = [version]
  }

  provisioner "local-exec" {
    command = "aws eks update-kubeconfig --name ${var.cluster_name}"
    when    = create
  }

  provisioner "local-exec" {
    command = "kubectl config unset clusters.${var.cluster_name}"
    when    = destroy
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**:
  - `cluster_name`: The name of the EKS cluster, with a default value of `"my-eks-cluster"`.
  - `vpc_id`: The VPC ID where the EKS cluster will be deployed, with a default value of `"vpc-12345678"`.
  - `subnet_ids`: A list of subnet IDs for the EKS cluster, with default values of `["subnet-12345678", "subnet-87654321"]`.
- **IAM Role**: An IAM role is created with the necessary trust policy to allow EKS to assume the role.
- **IAM Role Policy Attachment**: The IAM role is attached to the `AmazonEKSClusterPolicy` policy.
- **EKS Cluster**: The EKS cluster is created with the specified name, IAM role ARN, and VPC subnet IDs. Local-exec provisioners are used to update and unset the kubectl configuration during creation and destruction of the cluster, respectively.

