### Description
This Terraform program sets up an AWS S3 bucket and a DynamoDB table for managing Terraform state. The S3 bucket is configured with versioning, server-side encryption using AES256, and public access restrictions to prevent accidental deletion. The DynamoDB table is set up with a hash key named 'LockID' using the 'PAY_PER_REQUEST' billing mode for Terraform locking.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be changed as needed
}

resource "aws_s3_bucket" "terraform_state_bucket" {
  bucket = "terraform-state-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Prevent accidental deletion
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "terraform_state_lock" {
  name           = "terraform-state-lock"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}
```

