```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be changed as needed
}

resource "aws_s3_bucket" "example_bucket" {
  bucket = "example-bucket"
  acl    = "private"
  object_lock_enabled = true
}

resource "aws_s3_bucket_object_lock_configuration" "example_bucket_object_lock_configuration" {
  bucket = aws_s3_bucket.example_bucket.id

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 30
    }
  }
}
```

This configuration sets up the S3 bucket with the specified name and enables object lock. The object lock configuration is set to compliance mode with a retention period of 30 days. The `aws_s3_bucket_object_lock_configuration` resource depends on the `aws_s3_bucket` resource, ensuring that the bucket is created before configuring the object lock settings.

