### Description of the Terraform Program

This Terraform program sets up two AWS S3 buckets: one for CloudGoat data storage and another for web data storage. The CloudGoat data bucket is configured with private ACLs and ownership controls for ObjectWriter access. The web data bucket is configured with public access block settings to ignore public ACLs, block public ACLs, and restrict public buckets. Additionally, a bucket policy is created to allow the `s3:PutObject` action for all principals on the web data bucket's objects. An object named `order_data2.csv` is uploaded to the web data bucket from a local file path.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_suffix" {
  description = "Suffix to append to the bucket names"
  default     = "test"
}

resource "aws_s3_bucket" "cloudgoat_data_bucket" {
  bucket = "cloudgoat-data-${var.bucket_suffix}"
  acl    = "private"
}

resource "aws_s3_bucket_ownership_controls" "cloudgoat_data_bucket_ownership_controls" {
  bucket = aws_s3_bucket.cloudgoat_data_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket" "web_data_bucket" {
  bucket = "web-data-${var.bucket_suffix}"
  acl    = "private"
}

resource "aws_s3_bucket_object" "web_data_bucket_object" {
  bucket = aws_s3_bucket.web_data_bucket.id
  key    = "order_data2.csv"
  source = "./order_data2.csv"
}

resource "aws_s3_bucket_public_access_block" "web_data_bucket_public_access_block" {
  bucket                  = aws_s3_bucket.web_data_bucket.id
  ignore_public_acls      = true
  block_public_acls       = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "web_data_bucket_policy" {
  bucket = aws_s3_bucket.web_data_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "s3:PutObject"
        Principal = "*"
        Resource = "${aws_s3_bucket.web_data_bucket.arn}/*"
      }
    ]
  })
}
```

This Terraform configuration ensures that the specified S3 buckets are created with the appropriate settings and policies, and that an object is uploaded to the web data bucket.

