### Description
The Terraform program provided below creates a Redis instance using the AWS Elasticache service. The configuration includes essential parameters such as the engine type, engine version, node type, and number of cache nodes. Additionally, it sets up a basic IAM role and policy to allow the Elasticache service to perform necessary actions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "redis_instance_identifier" {
  description = "Identifier for the Redis instance"
  default     = "my-redis-instance"
}

variable "redis_engine" {
  description = "Engine type for the Redis instance"
  default     = "redis"
}

variable "redis_engine_version" {
  description = "Engine version for the Redis instance"
  default     = "6.x"
}

variable "redis_node_type" {
  description = "Node type for the Redis instance"
  default     = "cache.t3.micro"
}

variable "redis_num_cache_nodes" {
  description = "Number of cache nodes for the Redis instance"
  default     = 1
}

resource "aws_iam_role" "elasticache_role" {
  name = "elasticache-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "elasticache_policy" {
  name = "elasticache-policy"
  role = aws_iam_role.elasticache_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_elasticache_cluster" "redis_instance" {
  cluster_id           = var.redis_instance_identifier
  engine               = var.redis_engine
  engine_version       = var.redis_engine_version
  node_type            = var.redis_node_type
  num_cache_nodes      = var.redis_num_cache_nodes
  iam_role_arn         = aws_iam_role.elasticache_role.arn
  apply_immediately    = true
  auto_minor_version_upgrade = true
}
```

This Terraform configuration sets up a Redis instance in the `us-west-2` region with the specified parameters. It also creates an IAM role and policy to ensure that the Elasticache service has the necessary permissions to manage the instance.

