### Description
This Terraform program creates a 2-node Amazon Redshift cluster and attaches a resource policy to it. The clusters are configured with a default node type and database name. The resource policy allows all actions on the Redshift clusters.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "master_username" {
  description = "The master username for the Redshift cluster"
  default     = "admin"
}

variable "master_password" {
  description = "The master password for the Redshift cluster"
  default     = "SecurePassword123!"
}

resource "aws_redshift_cluster" "redshift_cluster_1" {
  cluster_identifier = "redshift_cluster_1"
  node_type          = "dc2.large"
  master_username    = var.master_username
  master_password    = var.master_password
  database_name      = "dev"
}

resource "aws_redshift_cluster" "redshift_cluster_2" {
  cluster_identifier = "redshift_cluster_2"
  node_type          = "dc2.large"
  master_username    = var.master_username
  master_password    = var.master_password
  database_name      = "dev"
}

resource "aws_redshift_resource_policy" "redshift_resource_policy" {
  resource_arn = aws_redshift_cluster.redshift_cluster_1.cluster_namespace_arn
  policy       = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = ["redshift:*"]
        Resource = aws_redshift_cluster.redshift_cluster_2.cluster_namespace_arn
      }
    ]
  })
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Two variables, `master_username` and `master_password`, are defined with default values. These are used to set the master credentials for the Redshift clusters.
- **Redshift Clusters**: Two Redshift clusters (`redshift_cluster_1` and `redshift_cluster_2`) are created with the specified node type and database name.
- **Resource Policy**: A resource policy is attached to the first Redshift cluster, allowing all actions on the second Redshift cluster. The policy uses the `cluster_namespace_arn` of both clusters to define the resources.

