### Description
This Terraform program creates a Lambda function, a DynamoDB table with a stream enabled, and a Lambda event source mapping that connects the DynamoDB stream to the Lambda function. It also includes an IAM role for the Lambda function and a permission to allow the DynamoDB service to invoke the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "my_lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_dynamodb_table" "my_dynamodb_table" {
  name           = "my_dynamodb_table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"
  stream_enabled = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_lambda_function" "my_lambda_function" {
  function_name = "my_lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"
}

resource "aws_lambda_permission" "allow_dynamodb_invocation" {
  statement_id  = "AllowDynamoDBInvocation"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.my_lambda_function.function_name
  principal     = "dynamodb.amazonaws.com"
  source_arn    = aws_dynamodb_table.my_dynamodb_table.stream_arn
}

resource "aws_lambda_event_source_mapping" "my_lambda_event_source_mapping" {
  function_name = aws_lambda_function.my_lambda_function.function_name
  event_source_arn = aws_dynamodb_table.my_dynamodb_table.stream_arn
  batch_size      = 10
  starting_position = "LATEST"
}
```

This configuration sets up the necessary components to create a Lambda function that is triggered by changes in a DynamoDB table. The IAM role and policy attachments ensure that the Lambda function has the necessary permissions to execute and be invoked by DynamoDB.

