### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "sagemaker_execution_role" {
  name = "sagemaker-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_full_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
  role       = aws_iam_role.sagemaker_execution_role.name
}

resource "aws_sagemaker_domain" "sagemaker_domain" {
  auth_mode            = "IAM"
  domain_name          = "my_sagemaker_domain"
  subnet_ids           = ["subnet-12345678", "subnet-87654321"]
  vpc_id               = "vpc-12345678"
  execution_role_arn   = aws_iam_role.sagemaker_execution_role.arn

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_execution_role.arn
  }
}

resource "aws_sagemaker_image" "sagemaker_image" {
  image_name = "my-sagemaker-image"
  role_arn   = aws_iam_role.sagemaker_execution_role.arn
}

resource "aws_sagemaker_space" "sagemaker_space" {
  domain_id = aws_sagemaker_domain.sagemaker_domain.id
  space_name = "my_sagemaker_space"

  ownership_settings {
    owner_user_profile_name = "default"
  }

  space_settings {
    kernel_gateway_app_settings {
      custom_image {
        image_name = aws_sagemaker_image.sagemaker_image.image_name
      }
      default_resource_spec {
        sagemaker_image_arn = aws_sagemaker_image.sagemaker_image.arn
      }
