### Description of the Terraform Program

This Terraform program creates two AWS EC2 instances running the latest Amazon Linux AMI in private subnets. Both instances share a single Amazon Elastic File System (EFS) for persistent storage. The program includes necessary configurations for VPC, subnets, security groups, and IAM roles to ensure proper access and security.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_type" {
  description = "The type of EC2 instance to launch"
  default     = "t3.micro"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "security_group_egress_rules" {
  description = "Egress rules for the security group"
  type        = list(map(string))
  default     = [
    {
      protocol    = "-1"
      from_port   = 0
      to_port     = 0
      cidr_blocks = ["0.0.0.0/0"]
    }
  ]
}

data "aws_ami" "latest_ami" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "instance_sg" {
  vpc_id = aws_vpc.main.id

  dynamic "egress" {
    for_each = var.security_group_egress_rules
    content {
      from_port   = egress.value.from_port
      to_port     = egress.value.to_port
      protocol    = egress.value.protocol
      cidr_blocks = egress.value.cidr_blocks
    }
  }
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "ec2_instance_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "ec2_instance_policy" {
  name        = "ec2_instance_policy"
  description = "Policy for EC2 instances to access EFS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_instance_policy_attachment" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = aws_iam_policy.ec2_instance_policy.arn
}

resource "aws_efs_file_system" "shared_efs" {
  creation_token = "shared-efs"
}

resource "aws_efs_file_system_policy" "main" {
  file_system_id = aws_efs_file_system.shared_efs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Effect   = "Allow"
        Principal = {
          AWS = "*"
        }
      }
    ]
  })
}

resource "aws_instance" "instance_1" {
  ami           = data.aws_ami.latest_ami.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private_subnet_1.id
  security_groups = [aws_security_group.instance_sg.name]
  iam_instance_profile = aws_iam_role.ec2_instance_role.name

  tags = {
    Name = "Instance-1"
  }
}

resource "aws_instance" "instance_2" {
  ami           = data.aws_ami.latest_ami.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private_subnet_2.id
  security_groups = [aws_security_group.instance_sg.name]
  iam_instance_profile = aws_iam_role.ec2_instance_role.name

  tags = {
    Name = "Instance-2"
  }
}
```

This Terraform configuration sets up the necessary infrastructure to meet the requirements specified in the prompt. It includes the creation of a VPC, private subnets, security groups, IAM roles, and EFS file systems, ensuring that the EC2 instances can communicate with the EFS file system securely.

