### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes in the `us-east-2` region. The program includes the necessary resources such as a subnet, security group, and the MSK cluster itself. The subnet and security group are configured to work within a specified VPC, and the MSK cluster is set up to use these resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the MSK cluster will be deployed."
  default     = "vpc-12345678"
}

variable "kafka_version" {
  description = "The Kafka version to use for the MSK cluster."
  default     = "2.8.0"
}

resource "aws_subnet" "msk_subnet" {
  vpc_id            = var.vpc_id
  cidr_block        = "10.0.0.0/24"
  availability_zone = "us-east-2a"

  tags = {
    Name = "msk-subnet"
  }
}

resource "aws_security_group" "msk_security_group" {
  vpc_id = var.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed_msk_cluster"
  kafka_version          = var.kafka_version
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.msk_subnet.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  tags = {
    Name = "managed-msk-cluster"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-east-2` region.
- **Variables**: Two variables are defined with default values:
  - `vpc_id`: The ID of the VPC where the MSK cluster will be deployed.
  - `kafka_version`: The Kafka version to use for the MSK cluster.
- **Subnet Resource**: An AWS subnet is created within the specified VPC, CIDR block, and availability zone.
- **Security Group Resource**: An AWS security group is created to allow inbound traffic on port 9092 and outbound traffic on all ports.
- **MSK Cluster Resource**: A managed MSK cluster is created with the specified name, Kafka version, and number of broker nodes. The cluster uses the previously created subnet and security group.

