    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

resource "aws_cloudwatch_log_group" "msk_cluster_logs" {
  name = "msk-cluster-logs"
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_1.id]
    instance_type  = "m5.large"
    security_groups = [aws_security_group.msk_sg.id]
  }

  logging_info {
    cloudwatch_logs {
      enabled   = true
      log_group = aws_cloudwatch_log_group.msk_cluster_logs.name
    }
  }

  tags = {
    Name = "managed-msk-cluster"
  }
}
```

This Terraform configuration sets up a basic infrastructure for a managed MSK cluster in the `us-east-1` region, including networking components and logging to CloudWatch. Adjustments can be made to the VPC, subnet, and security group configurations as needed for your specific environment.

