### Description
This Terraform program creates a managed Amazon MSK (Managed Streaming for Kafka) cluster in the `us-east-1` region and configures it to log to an S3 bucket. The program includes the necessary resources such as an S3 bucket for logging, a subnet, and a security group for the MSK cluster. The dependencies between these resources are preserved through Terraform references.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "aws_s3_bucket_logging" "msk_bucket_logging" {
  bucket      = aws_s3_bucket.msk_logs_bucket.id
  target_bucket = aws_s3_bucket.msk_logs_bucket.id
  target_prefix = "msk-logs/"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.main.id
  name   = "msk-security-group"

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed_msk_cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.msk_subnet.id]
    instance_type  = "m5.large"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  logging_info {
    s3 {
      bucket  = aws_s3_bucket.msk_logs_bucket.id
      prefix  = "msk-logs/"
    }
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
- **S3 Bucket**: An S3 bucket named `msk-logs-bucket` is created for storing MSK logs. A random suffix is appended to ensure uniqueness.
- **S3 Bucket Logging**: The logging configuration for the S3 bucket is set up to log to itself with the prefix `msk-logs/`.
- **VPC and Subnet**: A VPC and a subnet within that VPC are created to host the MSK cluster.
- **Security Group**: A security group is created to allow inbound traffic on port 9092 (Kafka) from any IP address.
- **MSK Cluster**: The MSK cluster is created with the specified name, Kafka version, number of broker nodes, and configuration for logging to the S3 bucket.
- **Random String**: A random string resource is used to generate a unique suffix for the S3 bucket name.

