### Description
This Terraform program creates a managed Amazon MSK (Managed Streaming for Kafka) cluster in the `us-east-1` region and configures it to log to an Amazon Kinesis Firehose delivery stream. The program also sets up the necessary networking components, including a VPC, subnet, and security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create a subnet within the VPC
resource "aws_subnet" "msk_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

# Create a security group for the MSK cluster
resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_stream" {
  name        = "msk_firehose_stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose_role.arn
    bucket_arn         = aws_s3_bucket.logging_bucket.arn
    buffering_interval = 300
    buffering_size     = 5
    compression_format = "GZIP"
  }
}

# Create an S3 bucket for Firehose logs
resource "aws_s3_bucket" "logging_bucket" {
  bucket = "msk-firehose-logs-${random_string.bucket_suffix.result}"
}

# Create an IAM role for Firehose
resource "aws_iam_role" "firehose_role" {
  name = "msk_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the Firehose IAM role
resource "aws_iam_role_policy_attachment" "firehose_s3_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisFirehoseFullAccess"
  role       = aws_iam_role.firehose_role.name
}

# Create a random string suffix for the S3 bucket
resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

# Create the MSK cluster
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed_msk_cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.msk_subnet.id]
    instance_type  = "kafka.m5.large"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/managed_msk_cluster"
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_stream.name
      }
    }
  }
}
```

This Terraform configuration sets up the necessary components to create a managed MSK cluster in `us-east-1` and configure it to log to a Kinesis Firehose delivery stream. It includes a VPC, subnet, security group, Kinesis Firehose delivery stream, S3 bucket for logs, and an IAM role with the necessary permissions.

