resource "aws_subnet" "msk_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "msk-subnet"
  }
}

resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.main.id
  name   = "msk-security-group"

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

resource "aws_msk_serverless_cluster" "serverless_msk_cluster" {
  cluster_name = "serverless_msk_cluster"

  vpc_config {
    subnet_ids         = [aws_subnet.msk_subnet.id]
    security_group_ids = [aws_security_group.msk_security_group.id]
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  tags = {
    Name = "serverless_msk_cluster"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet**: A subnet is created within the VPC with a CIDR block of `10.0.1.0/24` in the `us-east-1a` availability zone.
4. **Security Group**: A security group is created to allow inbound traffic on port 9098 (commonly used for Kafka) from any IP address. Outbound traffic is allowed to any destination.
5. **MSK Serverless Cluster**: A serverless MSK cluster is created with the specified VPC configuration and security group. The cluster uses SASL/IAM for client authentication.

