### Description
This Terraform program creates a managed Amazon Managed Streaming for Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region. It also creates an MSK Connect custom plugin using a `debezium.zip` file stored in an S3 bucket and sets up an MSK Connect connector that uses this custom plugin to connect to the MSK cluster. The necessary IAM roles and security configurations are also defined.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# VPC, Subnet, and Security Group
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "msk_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "msk-subnet"
  }
}

resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "msk-security-group"
  }
}

# MSK Cluster
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.msk_subnet.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  tags = {
    Name = "managed-msk-cluster"
  }
}

# S3 Bucket and Object for MSK Connect Custom Plugin
resource "aws_s3_bucket" "msk_plugin_bucket" {
  bucket = "msk-plugin-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "msk-plugin-bucket"
  }
}

resource "aws_s3_object" "debezium_object" {
  bucket = aws_s3_bucket.msk_plugin_bucket.bucket
  key    = "debezium.zip"
  source = "path/to/debezium.zip"

  acl = "private"
}

# MSK Connect Custom Plugin
resource "aws_mskconnect_custom_plugin" "debezium_plugin" {
  name       = "debezium-plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn = aws_s3_bucket.msk_plugin_bucket.arn
      file_key   = aws_s3_object.debezium_object.key
    }
  }

  tags = {
    Name = "debezium-plugin"
  }
}

# IAM Role for MSK Connect Connector
resource "aws_iam_role" "msk_connector_role" {
  name = "msk-connector-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "msk-connector-role"
  }
}

# MSK Connect Connector
resource "aws_mskconnect_connector" "msk_connector" {
  name                = "msk-connector"
  kafkaconnect_version = "2.8.1"
  service_execution_role_arn = aws_iam_role.msk_connector_role.arn

  connector_configuration = jsonencode({
    "connector.class" = "io.debezium.connector.kafka.KafkaConnector",
    "tasks.max" = "1",
    "topics" = "your-topic-name",
    "kafka.bootstrap.servers" = aws_msk_cluster.managed_msk_cluster.bootstrap_brokers_tls,
    "key.converter" = "org.apache.kafka.connect.storage.StringConverter",
    "value.converter" = "org.apache.kafka.connect.json.JsonConverter",
    "value.converter.schemas.enable" = "false"
  })

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.managed_msk_cluster.bootstrap_brokers_tls
      vpc {
        security_groups = [aws_security_group.msk_security_group.id]
        subnets         = [aws_subnet.msk_subnet.id]
      }
    }
  }

  plugin {
    custom_plugin {
      arn = aws_mskconnect_custom_plugin.debezium_plugin.arn
    }
  }

  tags = {
    Name = "msk-connector"
  }
}

# Random String for S3 Bucket Name Uniqueness
resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This Terraform configuration sets up the required resources to create an MSK cluster, upload a custom plugin to S3, and configure an MSK Connect connector using the custom plugin. Ensure that the `source` path for the `aws_s3_object` resource points to the actual location of your `debezium.zip` file.

