### Description

This Terraform program creates an Amazon Managed Streaming for Apache Kafka (MSK) cluster with three broker nodes, configured for encryption at rest and open monitoring. It also sets up a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream. Additionally, it creates an MSK Connect custom plugin using a "debezium.zip" file and an MSK Connect connector that uses this custom plugin to connect to the MSK cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The VPC ID where the MSK cluster will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_cidr_block" {
  description = "The CIDR block for the subnet where the MSK cluster will be deployed."
  default     = "10.0.1.0/24"
}

variable "availability_zone" {
  description = "The availability zone where the subnet will be created."
  default     = "us-west-2a"
}

resource "aws_subnet" "subnet" {
  vpc_id            = var.vpc_id
  cidr_block        = var.subnet_cidr_block
  availability_zone = var.availability_zone
}

resource "aws_security_group" "security_group" {
  vpc_id = var.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet.id]
    instance_type  = "kafka.m5.large"
    security_groups = [aws_security_group.security_group.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    cloudwatch_logs {
      enabled   = true
      log_group = "/aws/msk/my-msk-cluster"
    }
  }
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = "my-msk-s3-bucket"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "my-firehose-stream"
  destination = "s3"

  extended_s3_configuration {
    role_arn       = aws_iam_role.firehose_role.arn
    bucket_arn     = aws_s3_bucket.s3_bucket.arn
    prefix         = "logs/"
    buffering_size = 5
    buffering_interval = 300
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_delivery_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisFirehoseFullAccess"
  role       = aws_iam_role.firehose_role.name
}

resource "aws_mskconnect_custom_plugin" "custom_plugin" {
  name             = "debezium-plugin"
  content_type     = "ZIP"
  location {
    s3_location {
      bucket_arn = aws_s3_bucket.s3_bucket.arn
      file_key   = "debezium.zip"
    }
  }
}

resource "aws_mskconnect_connector" "connector" {
  name               = "my-msk-connector"
  connector_type     = "CUSTOM"
  kafkaconnect_version = "2.8.0"

  capacity {
    auto_scaling {
      max_capacity = 1
      min_capacity = 1
      scale_in_policy {
        cpu_utilization_percentage = 20
      }
      scale_out_policy {
        cpu_utilization_percentage = 70
      }
    }
  }

  connector_configuration = {
    "connector.class"                       = "io.debezium.connector.kafka.KafkaConnector"
    "tasks.max"                             = "1"
    "topics"                                = "my-topic"
    "kafka.bootstrap.servers"               = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
    "key.converter"                         = "org.apache.kafka.connect.storage.StringConverter"
    "value.converter"                       = "org.apache.kafka.connect.json.JsonConverter"
    "value.converter.schemas.enable"        = "false"
    "plugin.name"                           = "debezium-plugin"
  }

  kafka_cluster {
    apache_kafka {
      bootstrap_servers = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
      vpc {
        security_groups = [aws_security_group.security_group.id]
        subnets         = [aws_subnet.subnet.id]
      }
    }
  }

  kafka_client_authentication {
    authentication_type = "NONE"
  }

  kafka_logs {
    cloudwatch_logs {
      enabled   = true
      log_group = "/aws/mskconnect/my-msk-connector"
    }
  }

  plugins {
    custom_plugin {
      arn = aws_mskconnect_custom_plugin.custom_plugin.arn
      revision = aws_mskconnect_custom_plugin.custom_plugin.latest_revision
    }
  }
}
```

