### Description
The Terraform program below creates an Amazon RDS MySQL cluster with 100 GB allocated storage in each availability zone. The program includes the necessary provider configuration and specifies the required attributes for the RDS cluster. It also sets up a default VPC and subnet group if they do not already exist, ensuring that the cluster has the necessary networking resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_cluster_identifier" {
  description = "Identifier for the RDS cluster"
  default     = "my-mysql-cluster"
}

variable "db_instance_class" {
  description = "Instance class for the RDS cluster instances"
  default     = "db.t3.medium"
}

variable "db_subnet_group_name" {
  description = "Name of the DB subnet group"
  default     = "my-db-subnet-group"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "availability_zones" {
  description = "List of availability zones"
  type        = list(string)
  default     = ["us-west-2a", "us-west-2b", "us-west-2c"]
}

# Create a VPC if it doesn't exist
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

# Create subnets in each availability zone
resource "aws_subnet" "subnet" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(var.availability_zones, count.index)
}

# Create a DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = var.db_subnet_group_name
  subnet_ids = aws_subnet.subnet.*.id
}

# Create the RDS MySQL cluster
resource "aws_rds_cluster" "my_sql_cluster" {
  engine                  = "mysql"
  engine_version          = "8.0"
  allocated_storage       = 100
  db_cluster_identifier   = var.db_cluster_identifier
  master_username         = "admin"
  master_password         = "password123"
  db_subnet_group_name    = aws_db_subnet_group.main.name
  availability_zones      = var.availability_zones
  skip_final_snapshot     = true
  backup_retention_period = 5
}
```

