### Description

This Terraform program creates two example subnets within a specified VPC and groups them into an AWS Neptune subnet group. The subnets are configured with specific CIDR blocks and availability zones. The Neptune subnet group is then used to manage these subnets for an AWS Neptune cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the subnets will be created."
  type        = string
  default     = "vpc-12345678"
}

variable "subnet_cidr_block_1" {
  description = "The CIDR block for the first subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_cidr_block_2" {
  description = "The CIDR block for the second subnet."
  type        = string
  default     = "10.0.2.0/24"
}

variable "availability_zone_1" {
  description = "The availability zone for the first subnet."
  type        = string
  default     = "us-west-2a"
}

variable "availability_zone_2" {
  description = "The availability zone for the second subnet."
  type        = string
  default     = "us-west-2b"
}

resource "aws_subnet" "example_subnet_1" {
  vpc_id            = var.vpc_id
  cidr_block        = var.subnet_cidr_block_1
  availability_zone = var.availability_zone_1
}

resource "aws_subnet" "example_subnet_2" {
  vpc_id            = var.vpc_id
  cidr_block        = var.subnet_cidr_block_2
  availability_zone = var.availability_zone_2
}

resource "aws_neptune_subnet_group" "example_neptune_subnet_group" {
  name       = "example_neptune_subnet_group"
  subnet_ids = [aws_subnet.example_subnet_1.id, aws_subnet.example_subnet_2.id]
  description = "Subnet group for AWS Neptune cluster"
}
```

This Terraform configuration sets up the necessary infrastructure for an AWS Neptune cluster by creating two subnets and grouping them into a Neptune subnet group. The subnets are configured with specific CIDR blocks and availability zones, and the Neptune subnet group is used to manage these subnets.

