### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Custom Neptune Cluster Parameter Group
resource "aws_neptune_cluster_parameter_group" "my_neptune_cluster_parameter_group" {
  family        = "neptune1"
  name          = "my-neptune-cluster-parameter-group"
  description   = "Custom parameter group for Neptune cluster"

  parameter {
    name  = "neptune_query_timeout"
    value = "60000"
  }
}

# Custom Neptune Instance Parameter Group
resource "aws_neptune_parameter_group" "my_neptune_instance_parameter_group" {
  family        = "neptune1"
  name          = "my-neptune-instance-parameter-group"
  description   = "Custom parameter group for Neptune instance"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }
}

# Neptune Subnet Group
resource "aws_neptune_subnet_group" "my_neptune_subnet_group" {
  name       = "my-neptune-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0"] # Example subnet ID

  tags = {
    Name = "MyNeptuneSubnetGroup"
  }
}

# Security Group for Neptune
resource "aws_security_group" "my_neptune_security_group" {
  name        = "my-neptune-security-group"
  description = "Security group for Neptune instance"
  vpc_id      = "vpc-0123456789abcdef0" # Example VPC ID

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/24"] # Example CIDR block
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Neptune Cluster
resource "aws_neptune_cluster" "my_neptune_cluster" {
  cluster_identifier              = "my-neptune-cluster"
  engine                          = "neptune"
  engine_version                  = "1.2.0.1"
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.my_neptune_cluster_parameter_group.name
  neptune_subnet_group_name         = aws_neptune_subnet_group.my_neptune_subnet_group.name
  vpc_security_group_ids            = [aws_security_group.my_neptune_security_group.id]
  backup_retention_period           = 5
  preferred_backup_window           = "07:00-09:00"
  preferred_maintenance_window      = "sun:07:00-sun:09:00"
  skip_final_snapshot               = true
}

# Neptune Cluster Instance
resource "aws_neptune_cluster_instance" "my_neptune_cluster_instance" {
  cluster_identifier              = aws_neptune_cluster.my_neptune_cluster.id
  instance_class                    = "db.r5.large"
  neptune_parameter_group_name      = aws_neptune_parameter_group.my_neptune_instance_parameter_group.name
  neptune_subnet_group_name         = aws_neptune_subnet_group.my_neptune_subnet_group.name
  engine                          = "neptune"
  engine_version                  = "1.2.0.1"
  preferred_backup_window           = "07:00-09:00"
  preferred_maintenance_window      = "sun:07:00-sun:09:00"
}
```

This Terraform configuration sets up a Neptune cluster with a custom parameter group, a Neptune instance with its own custom parameter group, and configures the instance to only accept connections from a specified subnet. The security group allows inbound traffic on port 8182 from the specified CIDR block.

