### Description

This Terraform program sets up the infrastructure for an autograder for a CS class. It includes an AWS S3 bucket to store the results of the autograding process and an AWS CodeBuild project to run students' code stored on GitHub. The program also creates an IAM role that the CodeBuild project will assume to perform its tasks.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name = "AutograderResultsBucket"
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "CodeBuildServiceRole"
  }
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "codebuild-policy"
  role = aws_iam_role.codebuild_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "arn:aws:s3:::${aws_s3_bucket.autograder_results_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_codebuild_project" "autograder_codebuild_project" {
  name         = "autograder-codebuild-project"
  service_role = aws_iam_role.codebuild_service_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    report_build_status = true
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type         = "LINUX_CONTAINER"
  }

  artifacts {
    type   = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
  }

  tags = {
    Name = "AutograderCodeBuildProject"
  }
}
```

This Terraform configuration sets up the necessary AWS resources to support an autograder system. The S3 bucket is configured to store the results, the IAM role provides the necessary permissions for CodeBuild, and the CodeBuild project is set up to pull code from GitHub and store the results in the S3 bucket.

