### Description of the Terraform Program

This Terraform program sets up the following AWS infrastructure:

1. **AWS S3 Bucket**: A bucket named `codebuild-output-bucket` to store the output of AWS CodeBuild projects.
2. **AWS VPC**: A Virtual Private Cloud (VPC) with a CIDR block of `10.0.0.0/16`.
3. **AWS Subnet**: A subnet within the VPC with a CIDR block of `10.0.0.0/24`.
4. **AWS Security Group**: A security group linked to the VPC with no ingress or egress rules to block internet access.
5. **AWS CodeBuild Project**: A CodeBuild project configured to use the S3 bucket for storing build artifacts, with a specific environment and source configuration, and linked to the VPC.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "codebuild_output_bucket" {
  bucket = "codebuild-output-bucket"
  acl    = "private"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main_subnet" {
  vpc_id     = aws_vpc.main_vpc.id
  cidr_block = "10.0.0.0/24"
}

resource "aws_security_group" "main_sg" {
  vpc_id = aws_vpc.main_vpc.id
  ingress {
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
}

resource "aws_codebuild_project" "students_codebuild_project" {
  name         = "students-codebuild-project"
  service_role = aws_iam_role.codebuild_service_role.arn

  artifacts {
    type   = "S3"
    location = "${aws_s3_bucket.codebuild_output_bucket.bucket}"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    location        = "github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id             = aws_vpc.main_vpc.id
    subnets            = [aws_subnet.main_subnet.id]
    security_group_ids = [aws_security_group.main_sg.id]
  }
}
```

