### Description of the Terraform Program

This Terraform program sets up an AWS infrastructure to host a web service that allows users to upload cat pictures and retrieve random cat pictures. The service uses Amazon API Gateway to handle HTTP requests and Amazon S3 to store the uploaded cat pictures. The program includes the following components:

1. **S3 Bucket**: A private S3 bucket named `cat-pictures-bucket` to store the uploaded cat pictures.
2. **API Gateway REST API**: A REST API named `cat-pictures-api` to handle incoming HTTP requests.
3. **API Gateway Resources and Methods**:
   - **Upload Resource**: A resource named `upload` to handle file uploads.
   - **Random Resource**: A resource named `random` to provide random cat pictures.
4. **API Gateway Integrations**:
   - **Upload Integration**: An integration to handle POST requests for uploading cat pictures.
   - **Random Integration**: An integration to handle GET requests for retrieving random cat pictures.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${var.region}:s3:path/${aws_s3_bucket.cat_pictures_bucket.bucket}/upload"
}

resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "random"
}

resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random_resource.id
  http_method             = aws_api_gateway_method.random_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "GET"
  uri                     = "arn:aws:apigateway:${var.region}:s3:path/${aws_s3_bucket.cat_pictures_bucket.bucket}/random"
}

variable "environment" {
  description = "Environment name for the S3 bucket"
  default     = "dev"
}

variable "region" {
  description = "AWS region for the resources"
  default     = "us-west-2"
}
