### Description

This Terraform program sets up an AWS infrastructure for a REST API named "caas" with endpoints for managing cat information. The API includes two methods, `GET` and `PUT`, each linked to a corresponding AWS Lambda function. Additionally, it provisions an S3 bucket to store cat pictures and a DynamoDB table to store cat information with a single keyed attribute, "name". The necessary IAM roles and permissions are also configured to ensure proper access between the API Gateway, Lambda functions, and other AWS services.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Lambda Functions
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Functions
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "Policy for Lambda functions to access S3 and DynamoDB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::cat-pictures-bucket/*"
      },
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:dynamodb:us-west-2:*:table/cat-info-table"
      }
    ]
  })
}

# Attach IAM Policy to Lambda Role
resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  policy_arn = aws_iam_policy.lambda_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# API Gateway Rest API
resource "aws_api_gateway_rest_api" "caas_api" {
  name        = "caas"
  description = "API Gateway for managing cat information"
}

# API Gateway Resource for "cat"
resource "aws_api_gateway_resource" "caas_cat_resource" {
  rest_api_id = aws_api_gateway_rest_api.caas_api.id
  parent_id   = aws_api_gateway_rest_api.caas_api.root_resource_id
  path_part   = "cat"
}

# API Gateway Method for GET
resource "aws_api_gateway_method" "caas_get_method" {
  rest_api_id   = aws_api_gateway_rest_api.caas_api.id
  resource_id   = aws_api_gateway_resource.caas_cat_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

# API Gateway Method for PUT
resource "aws_api_gateway_method" "caas_put_method" {
  rest_api_id   = aws_api_gateway_rest_api.caas_api.id
  resource_id   = aws_api_gateway_resource.caas_cat_resource.id
  http_method   = "PUT"
  authorization = "NONE"
}

# Lambda Function for GET Method
resource "aws_lambda_function" "caas_get_lambda" {
  function_name = "caas_get_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      TABLE_NAME = aws_dynamodb_table.cat_info_table.name
    }
  }
}

# Lambda Function for PUT Method
resource "aws_lambda_function" "caas_put_lambda" {
  function_name = "caas_put_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      TABLE_NAME = aws_dynamodb_table.cat_info_table.name
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

# S3 Bucket for Cat Pictures
resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket"
}

# DynamoDB Table for Cat Information
resource "aws_dynamodb_table" "cat_info_table" {
  name           = "cat-info-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "name"

  attribute {
    name = "name"
    type = "S"
  }
}
