### Description of the Terraform Program

This Terraform program sets up an AWS CloudFront distribution with an S3 origin, configures default cache behavior, restrictions, and viewer certificate. It also creates an AWS Route53 zone and two Route53 records linked to the hosted zone. Additionally, it sets up a CloudFront origin access control resource to secure the S3 origin.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "VideoContentBucket"
  }
}

resource "aws_cloudfront_origin_access_control" "video_content_oac" {
  name                           = "video-content-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior               = "always"
  signing_protocol               = "sigv4"

  tags = {
    Name = "VideoContentOAC"
  }
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_200"
  retain_on_delete    = false
  wait_for_deployment = true

  origin {
    domain_name              = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_id                = "s3_video_content_origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.video_content_oac.id
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods    = ["GET", "HEAD"]
    target_origin_id  = "s3_video_content_origin"
    viewer_protocol_policy = "allow-all"
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name = "VideoContentDistribution"
  }
}

resource "aws_route53_zone" "netflix_com_zone" {
  name = "netflix.com"

  tags = {
    Name = "NetflixComZone"
  }
}

resource "aws_route53_record" "netflix_com_record_1" {
  name    = "www"
  type    = "A"
  zone_id = aws_route53_zone.netflix_com_zone.zone_id
  ttl     = 300
  records = [aws_cloudfront_distribution.video_content_distribution.domain_name]
}

resource "aws_route53_record" "netflix_com_record_2" {
  name    = "video"
  type    = "CNAME"
  zone_id = aws_route53_zone.netflix_com_zone.zone_id
  ttl     = 300
  records = [aws_cloudfront_distribution.video_content_distribution.domain_name]
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **S3 Bucket**: An S3 bucket named `video-content-bucket-<random_suffix>` is created with private ACL.
3. **CloudFront Origin Access Control**: A CloudFront origin access control resource is created to secure the S3 origin.
4. **CloudFront Distribution**: A CloudFront distribution is set up with the S3 bucket as the origin, default cache behavior configured for GET and HEAD methods, restrictions for specific geographic locations, and a default viewer certificate.
5. **Route53 Zone**: A Route53 zone for `netflix.com` is created.
6. **Route53 Records**: Two Route53 records (`www` and `video`) are created to point to the CloudFront distribution's domain name.
7. **Random String**: A random string resource is used to append a suffix to the S3 bucket name to ensure uniqueness.

