### Description
The Terraform program below sets up the infrastructure for a video streaming site using AWS Load Balancing. It includes an Application Load Balancer (ALB) to distribute incoming traffic across multiple target servers. The ALB is configured with necessary subnets and security groups. Additionally, a Kinesis Video Stream is created to handle video streaming data. The program ensures that all required attributes are specified and uses default values where necessary.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Security Group for the Load Balancer
resource "aws_security_group" "lb_sg" {
  name        = "video-streaming-lb-sg"
  description = "Security group for the video streaming load balancer"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Subnets for the Load Balancer
resource "aws_subnet" "subnet1" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  availability_zone = "us-west-2a"
  cidr_block        = "10.0.1.0/24"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  availability_zone = "us-west-2b"
  cidr_block        = "10.0.2.0/24"
}

# Application Load Balancer
resource "aws_lb" "video_streaming_load_balancer" {
  name               = "video-streaming-alb"
  internal           = false
  load_balancer_type = "application"

  security_groups = [aws_security_group.lb_sg.id]
  subnets         = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]

  listener {
    protocol    = "HTTP"
    port        = 80
    default_action {
      type             = "fixed-response"
      fixed_response {
        content_type = "text/plain"
        message_body = "Hello, World!"
        status_code  = "200"
      }
    }
  }
}

# Kinesis Video Stream
resource "aws_kinesis_video_stream" "main" {
  name                = "video-streaming-kvs"
  data_retention_in_hours = 24
}
```

### Notes
- **VPC ID**: Replace `"vpc-12345678"` with your actual VPC ID.
- **Subnets**: Adjust the `availability_zone` and `cidr_block` values to match your network configuration.
- **Security Group**: The security group allows HTTP traffic on port 80 from any IP address. This is for demonstration purposes and should be restricted in a production environment.
- **Load Balancer**: The ALB is configured to return a "Hello, World!" response for demonstration. Replace the `default_action` with appropriate routing rules for your application.
- **Kinesis Video Stream**: The stream is set to retain data for 24 hours. Adjust the retention period as needed.

