### Description of the Terraform Program

This Terraform program sets up the infrastructure for a video streaming site with multiple servers to balance load using AWS services. The program includes:

1. **AWS VPC**: A Virtual Private Cloud to contain the network resources.
2. **AWS Subnet**: A subnet within the VPC.
3. **AWS Security Group**: A security group to control inbound and outbound traffic to the EC2 instances.
4. **AWS EC2 Instance**: An EC2 instance running in the subnet and secured by the security group.
5. **AWS Load Balancer**: An Application Load Balancer to distribute incoming traffic across multiple targets.
6. **AWS Load Balancer Target Group**: A target group for the load balancer to manage the registered targets.
7. **AWS Route53 Zone**: A DNS zone for the domain.
8. **AWS Route53 Record**: A DNS record to point the domain to the load balancer.

The dependencies between these resources are managed to ensure proper deployment order.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "video_streaming_subnet" {
  vpc_id            = aws_vpc.video_streaming_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "video_streaming_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "video_streaming_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.video_streaming_subnet.id
  security_groups = [aws_security_group.video_streaming_sg.name]

  tags = {
    Name = "video-streaming-instance"
  }
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = aws_subnet.video_streaming_subnet.id
  }

  security_groups = [aws_security_group.video_streaming_sg.id]
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "example.com"
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_lb.video_streaming_lb.dns_name
    zone_id                = aws_lb.video_streaming_lb.zone_id
    evaluate_target_health = true
  }
}
```

