### Description of the Terraform Program

This Terraform program sets up an AWS infrastructure including a VPC, subnets, security groups, an Application Load Balancer (ALB), a target group, a listener, and Route53 records. The VPC has a CIDR block of `10.0.0.0/16`, and it contains three subnets with CIDR blocks `10.0.4.0/24`, `10.0.5.0/24`, and `10.0.6.0/24`. A security group is created to allow ingress from the VPC IP range and egress to any IP on port 80 using TCP. An ALB is configured with a target group and listener, and Route53 records are set up for the domain `test-video-stream.com`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "my_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.4.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.5.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet3" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.6.0/24"
  availability_zone = "us-west-2c"
}

resource "aws_security_group" "my_security_group" {
  vpc_id = aws_vpc.my_vpc.id
  name   = "my_security_group"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.my_vpc.cidr_block]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "my_lb" {
  name               = "my_lb"
  load_balancer_type = "application"
  security_groups    = [aws_security_group.my_security_group.id]

  subnet_mapping {
    subnet_id = aws_subnet.subnet1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet2.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet3.id
  }
}

resource "aws_lb_target_group" "my_lb_target_group" {
  name     = "my_lb_target_group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.my_vpc.id
}

resource "aws_lb_listener" "my_lb_listener" {
  load_balancer_arn = aws_lb.my_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.my_lb_target_group.arn
  }
}

resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Ubuntu
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.subnet1.id
  security_groups = [aws_security_group.my_security_group.name]

  tags = {
    Name = "WebServer"
  }
}

resource "aws_lb_target_group_attachment" "web_server_attachment" {
  target_group_arn = aws_lb_target_group.my_lb_target_group.arn
  target_id        = aws_instance.web_server.id
  port             = 80
}

resource "aws_route53_zone" "my_domain" {
  name = "test-video-stream.com"
}

resource "aws_route53_record" "lb_record" {
  zone_id = aws_route53_zone.my_domain.zone_id
  name    = "lb"
  type    = "A"
  alias {
    name                   = aws_lb.my_lb.dns_name
    zone_id                = aws_lb.my_lb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "ipv6_record" {
  zone_id = aws_route53_zone.my_domain.zone_id
  name    = ""
  type    = "AAAA"
  alias {
    name                   = aws_lb.my_lb.dns_name
    zone_id                = aws_lb.my_lb.zone_id
    evaluate_target_health = true
  }
}
