### Description
This Terraform program provisions a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS services like RDS, subnets, and KMS for encryption. The configuration includes a custom parameter group for PostgreSQL settings, a security group to manage access, and ensures high availability with multi-AZ deployment. The database instance is encrypted using a KMS key.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the database instance."
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "db_instance_class" {
  description = "The instance class for the database instance."
  default     = "db.t3.medium"
}

variable "allocated_storage" {
  description = "The allocated storage size for the database instance in gigabytes."
  default     = 20
}

variable "engine_version" {
  description = "The engine version for the PostgreSQL database."
  default     = "13.7"
}

variable "db_name" {
  description = "The name of the database."
  default     = "mydatabase"
}

variable "master_username" {
  description = "The master username for the database."
  default     = "admin"
}

variable "master_password" {
  description = "The master password for the database."
  default     = "securepassword123"
}

resource "aws_kms_key" "postgres_kms_key" {
  description             = "KMS key for encrypting the PostgreSQL database"
