### Description

This Terraform program provisions a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS services like RDS, subnets, and KMS for encryption. The configuration includes a custom parameter group for PostgreSQL settings, a security group to manage access, and ensures high availability through multi-AZ deployment. The database instance is configured with specific parameters such as storage size, engine version, instance class, and backup retention period.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database instance will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs where the database instance will be deployed."
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_kms_key" "db_encryption_key" {
  description             = "KMS key for encrypting the database instance"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_security_group" "db_security_group" {
  name        = "postgres-db-sg"
  description = "Security group for PostgreSQL database"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Example CIDR block, replace with actual allowed IPs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "postgres_param_group" {
  name   = "postgres-param-group"
  family = "postgres13"

  parameter {
    name  = "rds.logical_replication"
    value = "1"
  }

  parameter {
    name  = "max_connections"
    value = "200"
  }
}

resource "aws_db_instance" "postgres_db_instance" {
  identifier              = "my-postgres-db"
  instance_class          = "db.t3.micro"
  engine                  = "postgres"
  engine_version          = "13.4"
  allocated_storage       = 20
  multi_az                = true
  backup_retention_period = 7
  vpc_security_group_ids  = [aws_security_group.db_security_group.id]
  parameter_group_name    = aws_db_parameter_group.postgres_param_group.name
  kms_key_id              = aws_kms_key.db_encryption_key.arn
  db_subnet_group_name    = "my-db-subnet-group"  # Ensure this subnet group exists or create it
}
```

### Notes

1. **VPC and Subnet IDs**: The `vpc_id` and `subnet_ids` variables are provided with default values. You should replace these with your actual VPC and subnet IDs.
2. **Security Group Ingress Rules**: The security group allows inbound traffic on port 5432 from the specified CIDR block. Adjust the `cidr_blocks` to match your network's requirements.
3. **DB Subnet Group**: Ensure that the `db_subnet_group_name` matches an existing DB subnet group in your AWS account. If it doesn't exist, you need to create it separately.
4. **Parameter Group Parameters**: The example includes two parameters (`rds.logical_replication` and `max_connections`). You can add more parameters as needed based on your requirements.

