### Description

This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the necessary components such as a VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The configuration ensures that all resources are properly interconnected and secured.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "instance_class" {
  description = "Instance class for the RDS Aurora MySQL cluster"
  default     = "db.t3.medium"
}

variable "allocated_storage" {
  description = "Allocated storage for the RDS Aurora MySQL cluster"
  default     = 20
}

variable "backup_retention_period" {
  description = "Backup retention period in days"
  default     = 7
}

variable "db_name" {
  description = "Database name"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Database username"
  default     = "admin"
}

variable "db_password" {
  description = "Database password"
  default     = "securepassword123"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "db_subnets" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "db_proxy_sg" {
  name        = "db_proxy_sg"
  description = "Security group for the DB proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "db_proxy_role" {
  name = "db_proxy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_rds_cluster" "aurora_mysql_cluster" {
  engine               = "aurora-mysql"
  engine_version       = "8.0.mysql_aurora.3.02.0"
  instance_class       = var.instance_class
  allocated_storage    = var.allocated_storage
  backup_retention_period = var.backup_retention_period
  db_subnet_group_name = aws_db_subnet_group.main.name
  master_username      = var.db_username
  master_password      = var.db_password
  database_name        = var.db_name
}

resource "aws_db_subnet_group" "main" {
  name       = "aurora-mysql-subnet-group"
  subnet_ids = aws_subnet.db_subnets[*].id
}

resource "aws_db_proxy" "aurora_mysql_proxy" {
  name                   = "aurora_mysql_proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.db_proxy_role.arn
  vpc_subnet_ids         = aws_subnet.db_subnets[*].id
  vpc_security_group_ids = [aws_security_group.db_proxy_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
    username    = var.db_username
  }
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name = "aurora-mysql-db-credentials"
}

resource "aws_secretsmanager_secret_version" "db_credentials_version" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}
```

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with a proxy, including necessary networking, security, and IAM configurations. Adjust the CIDR blocks, instance classes, and other parameters as needed for your specific environment.

