### Description
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the necessary networking components such as a VPC, subnets, and security groups. Additionally, it creates an IAM role for the proxy and uses AWS Secrets Manager for secure credential storage. The idle client timeout for the proxy is set to 1800 seconds, and debug logging is disabled.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create a subnet
resource "aws_subnet" "db_proxy_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a security group for the DB proxy
resource "aws_security_group" "db_proxy_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this for security best practices
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM role for the DB proxy
resource "aws_iam_role" "db_proxy_role" {
  name = "db-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an RDS Aurora MySQL cluster
resource "aws_rds_cluster" "aurora_mysql_cluster" {
  engine              = "aurora-mysql"
  engine_mode         = "serverless"
  engine_version      = "8.0.mysql_aurora.3.02.0"
  cluster_identifier  = "aurora-mysql-cluster"
  master_username     = "admin"
  master_password     = "securepassword123"
  db_subnet_group_name = "aurora-subnet-group"
  skip_final_snapshot = true
}

# Create a DB proxy
resource "aws_db_proxy" "aurora_mysql_proxy" {
  name                   = "aurora-mysql-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.db_proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.db_proxy_subnet.id]
  vpc_security_group_ids = [aws_security_group.db_proxy_sg.id]
  idle_client_timeout    = 1800
  debug_logging          = false

  auth {
    auth_scheme     = "SECRETS"
    description     = "Proxy authentication"
    iam_auth        = "DISABLED"
    secret_arn      = "arn:aws:secretsmanager:us-west-2:123456789012:secret:rds-db-credentials/aurora-mysql-cluster"
    username        = "admin"
  }
}
```

### Notes
- **VPC and Subnet**: A VPC and subnet are created to host the Aurora cluster and proxy.
- **Security Group**: A security group is configured to allow inbound traffic on port 3306 (MySQL). Adjust the ingress rules for better security.
- **IAM Role**: An IAM role is created with a trust policy allowing RDS to assume it.
- **Aurora Cluster**: An Aurora MySQL cluster is set up in serverless mode.
- **DB Proxy**: A DB proxy is created with the specified idle client timeout and debug logging disabled. The `secret_arn` should be replaced with a valid ARN from AWS Secrets Manager.

