### Description
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the necessary networking components such as VPC, subnets, and security groups. Additionally, it creates an IAM role and uses AWS Secrets Manager for secure credential storage. The RDS cluster has a backup retention period of 5 days and a preferred backup window from 7 AM to 9 AM.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "aurora-vpc"
  }
}

# Create subnets
resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "aurora-subnet1"
  }
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "aurora-subnet2"
  }
}

# Create a security group for the RDS cluster
resource "aws_security_group" "db_cluster_sg" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "aurora-db-cluster-sg"
  }
}

# Create a security group for the DB proxy
resource "aws_security_group" "db_proxy_sg" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "aurora-db-proxy-sg"
  }
}

# Create an IAM role for the DB proxy
resource "aws_iam_role" "db_proxy_role" {
  name = "aurora-db-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an RDS Aurora MySQL cluster
resource "aws_rds_cluster" "aurora_mysql_cluster" {
  engine                  = "aurora-mysql"
  engine_version          = "8.0.mysql_aurora.3.02.0"
  cluster_identifier      = "aurora-mysql-cluster"
  master_username         = "admin"
  master_password         = "securepassword123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.db_cluster_sg.id]
  skip_final_snapshot     = true
}

# Create a DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "aurora-db-subnet-group"
  subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
}

# Create a Secrets Manager secret for the RDS credentials
resource "aws_secretsmanager_secret" "db_credentials" {
  name = "aurora-db-credentials"
}

# Create a DB proxy
resource "aws_db_proxy" "aurora_mysql_proxy" {
  name                   = "aurora_mysql_proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.db_proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
  vpc_security_group_ids = [aws_security_group.db_proxy_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
    username    = "admin"
  }
}
```

