### Description
This Terraform program creates an Application Load Balancer named `test-lb-tf` in the AWS region `us-west-2`. The ALB is configured with two subnets and a security group. The ALB is not internal and has deletion protection enabled. The VPC ID for the subnets and security group is set to a synthetic default value (`vpc-12345678`). The CIDR blocks for the subnets are also set to synthetic default values (`10.0.1.0/24` and `10.0.2.0/24`).

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_security_group" "test_lb_sg" {
  name        = "test_lb_sg"
  description = "Security group for test-lb-tf"
  vpc_id      = "vpc-12345678"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "subnet1" {
  vpc_id            = "vpc-12345678"
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = "vpc-12345678"
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_lb" "test_lb_tf" {
  name               = "test-lb-tf"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.test_lb_sg.id]
  subnets            = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
  enable_deletion_protection = true
}
```

This configuration sets up the necessary resources to meet the requirements specified in the prompt. The ALB is configured to be publicly accessible, with deletion protection enabled, and it uses the specified security group and subnets.

