### Description
This Terraform program creates an Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The program includes the necessary resources such as the load balancer, target group, target group attachment, and an EC2 instance. The load balancer is configured to listen on port 80 and forward traffic to the target group, which in turn forwards traffic to the EC2 instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-load-balancer"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"  # Replace with your subnet ID
  }

  security_groups = ["sg-0123456789abcdef0"]  # Replace with your security group ID

  listener {
    protocol = "HTTP"
    port     = 80

    default_action {
      type             = "forward"
      target_group_arn = aws_lb_target_group.my_target_group.arn
    }
  }
}

resource "aws_lb_target_group" "my_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-0123456789abcdef0"  # Replace with your VPC ID

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_target_group_attachment" "my_target_group_attachment" {
  target_group_arn = aws_lb_target_group.my_target_group.arn
  target_id        = aws_instance.my_instance.id
  port             = 80
}

resource "aws_instance" "my_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2 in us-west-2
  instance_type = "t3.micro"

  subnet_id = "subnet-0123456789abcdef0"  # Replace with your subnet ID

  tags = {
    Name = "MyInstance"
  }
}
```

### Notes
- Replace the placeholder values for `subnet_id`, `security_groups`, and `vpc_id` with your actual AWS resource IDs.
- The `ami` value is set to a default Amazon Linux 2 AMI ID for the `us-west-2` region. Ensure this AMI is available in your region or replace it with a suitable AMI ID.
- The load balancer is configured to listen on port 80 and forward traffic to the target group, which in turn forwards traffic to the EC2 instance. Adjust the configuration as needed for your specific use case.

