LLM Output #0:
### Description
This Terraform program creates an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB). Both load balancers are configured within a VPC, and the necessary subnets are specified. The program also includes IAM roles and policies required for the load balancers to function correctly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zones" {
  description = "Availability zones for the subnets"
  type        = list(string)
  default     = ["us-west-2a", "us-west-2b"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "subnet" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(var.availability_zones, count.index)
}

resource "aws_lb" "network_load_balancer" {
  name            = "network-load-balancer"
  internal        = true
  load_balancer_type = "network"

  subnet_mapping {
    subnet_id = aws_subnet.subnet.*.id[count.index]
  }
}

resource "aws_lb" "application_load_balancer" {
  name            = "application-load-balancer"
  internal        = true
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = aws_subnet.subnet.*.id[count.index]
  }

  target_group_arns = [aws_lb_target_group.nlb_target_group.arn]
}

resource "aws_lb_target_group" "nlb_target_group" {
  name     = "nlb-target-group"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  target_type = "ip"

  health_check {
    interval            = 30
    path                = "/"
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_iam_role" "alb_role" {
  name = "alb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "alb_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticLoadBalancingV2ServiceRole"
  role       = aws_iam_role.alb_role.name
}

resource "aws_iam_role" "nlb_role" {
  name = "nlb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "nlb_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticLoadBalancingV2ServiceRole"
  role       = aws_iam_role.nlb_role.name
}
```

This Terraform program sets up an ALB that forwards traffic to an NLB within a VPC. It includes the necessary subnets, IAM roles, and policies to ensure proper functionality.

