  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}

resource "aws_lb_target_group" "target_group" {
  target_type = "lambda"
}

resource "aws_lb_target_group_attachment" "ec2_attach" {
  target_group_arn = aws_lb_target_group.target_group.arn
  target_id = aws_lambda_function.example.arn
}

LLM Output #0:
### Description
This Terraform program sets up an Application Load Balancer (ALB) with a Lambda Target Group. The ALB will forward incoming traffic to an AWS Lambda function. The program includes the necessary resources such as the ALB, Lambda function, and the target group attachment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-load-balancer"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"  # Replace with your subnet ID
  }

  security_groups = ["sg-0123456789abcdef0"]  # Replace with your security group ID

  enable_deletion_protection = false
}

resource "aws_lb_target_group" "my_lambda_target_group" {
  name     = "my-lambda-target-group"
  port     = 443
  protocol = "HTTPS"
  vpc_id   = "vpc-0123456789abcdef0"  # Replace with your VPC ID
  target_type = "lambda"
}

resource "aws_lb_target_group_attachment" "lambda_target_group_attachment" {
  target_group_arn = aws_lb_target_group.my_lambda_target_group.arn
  target_id        = aws_lambda_function.my_lambda_function.arn
}

resource "aws_lambda_function" "my_lambda_function" {
  function_name = "my-lambda-function"
  role          = "arn:aws:iam::123456789012:role/lambda-execution-role"  # Replace with your IAM role ARN
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "function.zip"  # Replace with your Lambda function ZIP file

  environment {
    variables = {
      LOG_LEVEL = "info"
    }
  }
}
```

### Notes
- Replace `"subnet-0123456789abcdef0"`, `"sg-0123456789abcdef0"`, and `"vpc-0123456789abcdef0"` with your actual subnet, security group, and VPC IDs.
- Replace `"arn:aws:iam::123456789012:role/lambda-execution-role"` with the ARN of your IAM role that has the necessary permissions for the Lambda function.
- Ensure that the `filename` points to the correct path of your Lambda function's deployment package.

