LLM Output #0:
### Description
This Terraform program creates a memory-optimized PostgreSQL database using AWS Aurora Serverless v2. The configuration includes an RDS cluster and an associated instance. The program also sets up an IAM role for the RDS cluster to manage backups and other operations. Default values are provided for required attributes where necessary.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_cluster_identifier" {
  description = "Identifier for the RDS cluster"
  default     = "memory-optimized-postgresql-cluster"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance"
  default     = "memory-optimized-postgresql-instance"
}

variable "master_username" {
  description = "Username for the RDS cluster"
  default     = "admin"
}

variable "master_password" {
  description = "Password for the RDS cluster"
  default     = "securepassword123!"
}

variable "backup_retention_period" {
  description = "Number of days to retain backups"
  default     = 7
}

variable "preferred_backup_window" {
  description = "Preferred backup window"
  default     = "07:00-09:00"
}

resource "aws_iam_role" "rds_backup_role" {
  name = "rds-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "rds_backup_policy" {
  name        = "rds-backup-policy"
  description = "Policy for RDS backup operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::my-rds-backups",
          "arn:aws:s3:::my-rds-backups/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_rds_backup_policy" {
  role       = aws_iam_role.rds_backup_role.name
  policy_arn = aws_iam_policy.rds_backup_policy.arn
}

resource "aws_rds_cluster" "memory_optimized_postgresql_cluster" {
  cluster_identifier      = var.db_cluster_identifier
  engine                  = "aurora-postgresql"
  engine_mode             = "serverless"
  master_username         = var.master_username
  master_password         = var.master_password
  backup_retention_period = var.backup_retention_period
  preferred_backup_window = var.preferred_backup_window
  iam_database_authentication_enabled = true
  db_subnet_group_name    = "default"  # Ensure this subnet group exists in your AWS account
  skip_final_snapshot     = true

  scaling_configuration {
    auto_pause            = true
    max_capacity          = 8
    min_capacity          = 2
    seconds_until_auto_pause = 300
  }

  timeouts {
    create = "1h"
    update = "1h"
    delete = "1h"
  }
}

resource "aws_rds_cluster_instance" "memory_optimized_postgresql_instance" {
  cluster_identifier = aws_rds_cluster.memory_optimized_postgresql_cluster.id
  engine             = "aurora-postgresql"
  instance_class     = "db.serverless"

  timeouts {
    create = "1h"
    update = "1h"
    delete = "1h"
  }
}
```

This Terraform configuration sets up a memory-optimized PostgreSQL database using AWS Aurora Serverless v2. It includes an RDS cluster and an associated instance, along with an IAM role and policy for managing backups. Default values are provided for required attributes, ensuring the configuration is deployable with Terraform version 1.9.8 and AWS provider version 5.75.

