  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_vpc" "base" {
  cidr_block           = "10.1.0.0/24"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_vpc_peering_connection" "pike" {
  vpc_id      = aws_vpc.base.id
  peer_vpc_id = aws_vpc.peer.id

  accepter {
    allow_remote_vpc_dns_resolution = true
  }

  requester {
    allow_remote_vpc_dns_resolution = true
  }
}
```

This Terraform configuration sets up the two VPCs and establishes a VPC peering connection between them, ensuring they can communicate with each other. The `enable_dns_support` and `enable_dns_hostnames` options are set to `true` for both VPCs to facilitate proper DNS resolution within the VPCs.

